"""Listing scores and ranking (Section 5). Two methods, chosen by `scoring.method`:

- five_part (default): every listing that passed the hard rules gets five parts, each 0-1,
  weighted per buyer type into a 0-100 score, plus the reasons that earned it:
  deal (price against the market price for its condition), condition, trust (scam risk and
  listing signals), convenience (pickup distance or shipping) and identification confidence.
- plan: Plan v2's U = w1 * P + w2 * C + w3 * T (`personas` weights), kept for comparison.
"""

from datetime import date
from typing import Any

from src.config import load_config
from src.schemas import CONDITION_WORDS, Condition, EvaluatedListing, Persona
from src.tools.prices import condition_adjusted


def compute_utility(
    total: float,
    budget: float,
    condition: Condition,
    risk: float,
    persona: Persona,
    config: dict[str, Any] | None = None,
) -> float:
    """Plan v2's U = w1 * P + w2 * C + w3 * T.

    - P = 1 - (total / budget), clipped to [0, 1]
    - C = condition score from config (NM 1.0, LP 0.8, MP 0.6, HP 0.4, DMG 0.2, unknown 0.5)
    - T = 1 - risk, clipped to [0, 1]
    """
    if budget <= 0:
        raise ValueError("budget must be positive")

    cfg = config or load_config()
    weights = cfg["personas"][persona]
    cond_scores = cfg["condition_utility_scores"]

    p_score = max(0.0, min(1.0, 1.0 - (total / budget)))
    c_score = float(cond_scores.get(condition, cond_scores["unknown"]))
    t_score = max(0.0, min(1.0, 1.0 - risk))

    utility = (
        weights["price"] * p_score + weights["condition"] * c_score + weights["trust"] * t_score
    )
    return round(utility, 6)


def _clip(v: float) -> float:
    return max(0.0, min(1.0, v))


def _days_old(listed_at: str | None, today: date) -> int | None:
    try:
        return (today - date.fromisoformat(listed_at)).days if listed_at else None
    except ValueError:
        return None


def score_parts(
    item: EvaluatedListing, budget: float | None, config: dict[str, Any], today: date | None = None
) -> tuple[dict[str, float], list[tuple[str, str, float]]]:
    """The five parts (each 0-1) and candidate reasons as (part, words, strength)."""
    s = config["scoring"]
    x, total = item.listing, item.landed_cost.total
    reasons: list[tuple[str, str, float]] = []

    # Deal: the total against the market price for its condition. Without a market price,
    # against the budget (as the plan formula does); without either, neutral.
    if item.market_price:
        fair = condition_adjusted(item.market_price, x.condition, config)
        ratio = total / fair if fair else 1.0
        best, worst = s["deal_best_ratio"], s["deal_worst_ratio"]
        if ratio < config["thresholds"]["price_risk_med_ratio"]:
            deal = 0.5  # too cheap to be a deal: the scam risk score weighs it, not this part
        else:
            deal = _clip((worst - ratio) / (worst - best))
            if ratio <= 0.9:
                reasons.append(
                    ("deal", f"{round((1 - ratio) * 100)}% under the market price", deal)
                )
            elif ratio <= 1.1:
                reasons.append(("deal", "about the market price", 0.5))
    elif budget:
        deal = _clip(1 - total / budget)
    else:
        deal = 0.5

    cond_scores = config["condition_utility_scores"]
    condition = float(cond_scores.get(x.condition, cond_scores["unknown"]))
    if x.condition in ("NM", "LP"):
        reasons.append(("condition", CONDITION_WORDS[x.condition], condition))

    # Trust: scam risk, blended with what the listing itself shows.
    signals = []
    if x.photo_count is not None:
        signals.append(min(x.photo_count / s["photos_good"], 1.0))
        if x.photo_count >= s["photos_good"]:
            reasons.append(("trust", f"{x.photo_count} photos", 0.6))
    signals.append(min(len(x.raw_description) / s["description_good_chars"], 1.0))
    if len(x.raw_description) >= s["description_good_chars"]:
        reasons.append(("trust", "a detailed description", 0.5))
    if x.public_meetup:
        signals.append(1.0)
        reasons.append(("trust", "a public meetup offered", 0.8))
    elif x.delivery_type == "in_person":
        signals.append(0.7)
    age = _days_old(x.listed_at, today or date.today())
    if age is not None:
        signals.append(1.0 if age <= s["stale_days"] else 0.6)
    listing_signals = sum(signals) / len(signals)
    if x.pending:
        listing_signals *= 0.5
    share = s["trust_risk_share"]
    trust = _clip(share * (1 - item.risk_score) + (1 - share) * listing_signals)

    # Convenience: how far to drive for a pickup, or whether shipping is known.
    if x.delivery_type == "in_person" and x.distance_miles is not None:
        near, mid, far = s["pickup_miles"]
        d = x.distance_miles
        convenience = 1.0 if d <= near else 0.7 if d <= mid else 0.4 if d <= far else 0.2
        if d <= mid:
            reasons.append(("convenience", f"pickup about {round(d)} miles away", convenience))
    elif x.delivery_type == "shipping" and x.shipping is not None:
        convenience = s["convenience_shipping"]
    else:
        convenience = s["convenience_unknown"]

    parts = {
        "deal": round(deal, 4),
        "condition": round(condition, 4),
        "trust": round(trust, 4),
        "convenience": round(convenience, 4),
        "confidence": round(_clip(x.confidence), 4),
    }
    return parts, reasons


def score_listing(
    item: EvaluatedListing,
    budget: float | None,
    persona: Persona,
    config: dict[str, Any],
    today: date | None = None,
) -> EvaluatedListing:
    """The listing with utility_score (0-1), its five parts and up to 3 spoken reasons,
    strongest first for this buyer type."""
    weights = config["scoring"]["weights"][persona]
    parts, reasons = score_parts(item, budget, config, today)
    score = sum(weights[k] * v for k, v in parts.items())
    ranked = sorted(reasons, key=lambda r: -weights[r[0]] * r[2])
    return item.model_copy(
        update={
            "utility_score": round(score, 6),
            "score_parts": parts,
            "reasons": [words for _, words, _ in ranked[:3]],
        }
    )


def rank_listings(
    listings: list[EvaluatedListing],
    budget: float | None,
    persona: Persona,
    config: dict[str, Any] | None = None,
    today: date | None = None,
) -> list[EvaluatedListing]:
    """Score and rank surviving listings, best first. Ties go to the lower landed cost.

    With no budget (a consultative question), the plan formula measures P against the most
    expensive surviving listing, so the cheapest one gets the full price score.
    """
    cfg = config or load_config()
    method = cfg.get("scoring", {}).get("method", "five_part")
    scored: list[EvaluatedListing] = []
    plan_budget = budget
    if budget is None:
        totals = [x.landed_cost.total for x in listings if x.landed_cost and not x.rejected]
        plan_budget = max(totals, default=0.0) or 1.0

    for item in listings:
        if item.rejected:
            continue
        if item.landed_cost is None:
            raise ValueError(
                f"Listing {item.listing.listing_id} missing landed_cost before ranking."
            )
        if method == "plan":
            u = compute_utility(
                total=item.landed_cost.total,
                budget=plan_budget,
                condition=item.listing.condition,
                risk=item.risk_score,
                persona=persona,
                config=cfg,
            )
            scored.append(item.model_copy(update={"utility_score": u}))
        else:
            scored.append(score_listing(item, budget, persona, cfg, today))

    # Sort descending by utility, then ascending by landed cost total (tie-breaker)
    scored.sort(
        key=lambda x: (
            -(x.utility_score if x.utility_score is not None else -1.0),
            x.landed_cost.total if x.landed_cost is not None else float("inf"),
        )
    )
    return scored
